// The channel's custom counters: what (count) and (count.name) in custom commands write to.
$bCounters = [];
// Names come from custom command responses: (count.NAME) counts under NAME, plain (count) under the command's own name.
$bNames = [];
try { $r = $db->query("SELECT command, response FROM custom_commands"); while ($r && ($row = $r->fetch_assoc())) {
    $resp = (string) $row['response'];
    if (preg_match_all('/\(count\.(\w+)\)/', $resp, $m)) foreach ($m[1] as $n) $bNames[$n] = 0;
    if (strpos($resp, '(count)') !== false) $bNames[ltrim((string) $row['command'], '!')] = 0;
} } catch (Throwable $e) {}
try { $r = $db->query("SELECT command, count FROM custom_counts"); while ($r && ($row = $r->fetch_assoc())) { if (array_key_exists((string) $row['command'], $bNames)) $bNames[(string) $row['command']] = (int) $row['count']; } } catch (Throwable $e) {}
ksort($bNames, SORT_NATURAL | SORT_FLAG_CASE);
foreach (array_slice($bNames, 0, 200, true) as $n => $c) { if (preg_match('/^[A-Za-z0-9_-]{1,100}$/', (string) $n)) $bCounters[] = ['name' => (string) $n, 'count' => $c]; }
